import './Registrar_Usuario.css';
import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { GuardrUsuario } from '../../../Redux/Actions/Usuario/Action-user';

const RegistrarUsuario = ({ setView }) => {
  const dispatch = useDispatch();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });

  const [errors, setErrors] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });

  const validateEmail = (email) => {
    // Regex for email validation
    const re = /\S+@\S+\.\S+/;
    return re.test(email);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });

    // Clear errors as the user types
    setErrors({ ...errors, [name]: '' });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    // Check for empty fields
    let validationErrors = {};
    if (!formData.firstName) validationErrors.firstName = 'El nombre es obligatorio';
    if (!formData.lastName) validationErrors.lastName = 'El apellido es obligatorio';
    if (!formData.email) {
      validationErrors.email = 'El email es obligatorio';
    } else if (!validateEmail(formData.email)) {
      validationErrors.email = 'El email no es válido';
    }
    if (!formData.password) validationErrors.password = 'La contraseña es obligatoria';

    // If there are errors, set them in the state and do not submit
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    // Submit form if validation passes
    dispatch(GuardrUsuario(formData));
  };

  return (
    <div className="body-empresa-register">
      <div>
        <h2 className="Titulos">Registro de Usuario</h2>
        <form onSubmit={handleSubmit}>
          <div className="input-group-usuario">
            <label>
              Nombre:
              <input
                type="text"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
              />
              {errors.firstName && <span className="error">{errors.firstName}</span>}
            </label>
          </div>
          <div className="input-group-usuario">
            <label>
              Apellido:
              <input
                type="text"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
              />
              {errors.lastName && <span className="error">{errors.lastName}</span>}
            </label>
          </div>
          <div className="input-group-usuario">
            <label>
              Email:
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
              />
              {errors.email && <span className="error">{errors.email}</span>}
            </label>
          </div>
          <div className="input-group-usuario">
            <label>
              Contraseña:
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
              />
              {errors.password && <span className="error">{errors.password}</span>}
            </label>
          </div>
          <button type="submit" className="btn-Enviar">Registrarse</button>
        </form>
      </div>
      <div onClick={() => setView("login")} className="btn-Link">Ya tienes cuenta? Iniciar sesión</div>
    </div>
  );
};

export default RegistrarUsuario;
